import{_ as t,o as a,c as n,ah as o}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Digitisation","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/gestion-documentaire/numerisation.md","filePath":"src/en/guide/gestion-documentaire/numerisation.md"}'),s={name:"en/guide/gestion-documentaire/numerisation.md"};function i(r,e,h,c,l,d){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="digitisation" tabindex="-1">Digitisation <a class="header-anchor" href="#digitisation" aria-label="Permalink to &quot;Digitisation&quot;">​</a></h1><p>ERA brings paper in two ways: <strong>photographing the pages with a phone</strong>, for a document handed to you at the desk, and <strong>archive recovery</strong>, for a whole box of old files.</p><p>Either way, ERA <strong>reads the text</strong> on the images, so the document can be found by its content later. The reading happens in your browser: the document never leaves the school.</p><div class="info custom-block"><p class="custom-block-title">First reading</p><p>The first time a browser reads a text, it downloads the reading engine and the French and English models (a few MB), then keeps them. That first reading needs an internet connection and takes a little longer.</p></div><p>Reading makes documents <strong>searchable</strong> and <strong>suggests the people</strong> whose name appears. It does not fill in fields for you: always check what you classify.</p><h2 id="photograph-a-document-with-a-phone" tabindex="-1">Photograph a document with a phone <a class="header-anchor" href="#photograph-a-document-with-a-phone" aria-label="Permalink to &quot;Photograph a document with a phone&quot;">​</a></h2><ol><li>In the file, click <strong>File</strong> next to the type concerned.</li><li>Choose <strong>Photos of the pages</strong>.</li><li>Click <strong>Take a photo</strong> and photograph the first page, flat and well lit. Repeat for each page, in order. <strong>Choose images</strong> takes photos already on the phone.</li><li>Each page shows as a numbered thumbnail. The cross removes a bad page. The text of each page is read while you carry on.</li><li>Fill in the title, date and notes if needed, then click <strong>File</strong>.</li></ol><p>The pages, 20 at most, are gathered into <strong>one PDF</strong> in A4 format, in the order you took them. The document then goes the way of any filing: validated at once if you may validate it and the box is ticked, otherwise waiting to be checked.</p><p>In <strong>A file</strong> mode, the text of an image filed is read the same way. The text of PDFs is not read.</p><h2 id="find-a-document-by-its-content" tabindex="-1">Find a document by its content <a class="header-anchor" href="#find-a-document-by-its-content" aria-label="Permalink to &quot;Find a document by its content&quot;">​</a></h2><p>On the <strong>Documents</strong> page, the <strong>Search the documents</strong> field also searches the text read. Type for example a place of birth or a certificate number to find the documents that carry it.</p><h2 id="archive-recovery" tabindex="-1">Archive recovery <a class="header-anchor" href="#archive-recovery" aria-label="Permalink to &quot;Archive recovery&quot;">​</a></h2><p>A <strong>recovery campaign</strong> brings a paper archive in bulk, then classifies it document by document. It is for an administrator and the document manager, from the <strong>Documents</strong> space → <strong>Archive recovery</strong>.</p><h3 id="create-a-campaign" tabindex="-1">Create a campaign <a class="header-anchor" href="#create-a-campaign" aria-label="Permalink to &quot;Create a campaign&quot;">​</a></h3><p>Under <strong>New campaign</strong>, name it after the archive it brings in (for example &quot;Enrolment files 2019–2020&quot;), add notes if needed, then click <strong>Create the campaign</strong>.</p><p>The <strong>Campaigns</strong> list shows, for each, how many scans it holds and how many are left to classify.</p><h3 id="bring-the-scans-in" tabindex="-1">Bring the scans in <a class="header-anchor" href="#bring-the-scans-in" aria-label="Permalink to &quot;Bring the scans in&quot;">​</a></h3><p>Scan the box with the school&#39;s scanner or a phone, then, in the campaign, click <strong>Choose the scans</strong> and select all the files at once: PDF or images, 10 MB each at most.</p><p>ERA reads the text on each image then sends it, one at a time. The counter shows how far it has got. Keep the page open until the end. If a scan could not be sent, the counter says so: choose it again.</p><p>The scans brought in wait under <strong>To classify</strong>. Until they are classified they have no type and no file: only an administrator and the document manager see them, and they show neither in the files nor among the documents to check.</p><h3 id="classify-a-scan" tabindex="-1">Classify a scan <a class="header-anchor" href="#classify-a-scan" aria-label="Permalink to &quot;Classify a scan&quot;">​</a></h3><p>The campaign shows the first scan to classify, with the text read on it under <strong>Text read on the page</strong>. The numbers above it let you pick another.</p><ol><li>Choose the <strong>Document type</strong>, or <strong>Another type…</strong> to create one: name it and choose the file it goes in.</li><li>If the type goes in a student&#39;s or an employee&#39;s file, ERA suggests the people whose name is on the page, and ticks the first. Check it, or search for someone else by name with the magnifying glass.</li><li>Fill in the <strong>Title</strong> and the <strong>Date of the document</strong> if needed.</li><li>If you may validate this type, the <strong>I have checked it: validate it now</strong> box is ticked. Otherwise the document waits to be checked by those who validate this type.</li><li>Click <strong>Classify</strong>. The next scan shows.</li></ol><p>For a student, ERA suggests those whose <strong>last name and first given name</strong> are on the page, or whose registration number is, when the school uses them. For an employee, their full name is needed. Accents and capitals do not matter. A last name alone is not enough: it too often belongs to several students.</p><p>The last scans classified show at the bottom of the campaign, with their type, person and status. Once classified, a scan is a document like any other, in its file.</p>',25)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
